// Scenarios are generated by the real PowerShell scoring helper; no system settings are changed.
const fs=require('fs'),path=require('path'),http=require('http');
const {chromium}=require(process.env.CSL_PLAYWRIGHT_MODULE || 'playwright');
const root=process.env.CSL_SCORE_FIXTURES || require('path').join(require('os').tmpdir(),'claude-score-qa-'+Date.now());
fs.mkdirSync(root,{recursive:true});
if(!fs.existsSync(path.join(root,'weighted-report.json'))){const r=require('child_process').spawnSync(path.join(process.env.SystemRoot||'C:/Windows','System32/WindowsPowerShell/v1.0/powershell.exe'),['-NoProfile','-ExecutionPolicy','Bypass','-File',path.join(__dirname,'verify-assessment.ps1'),'-ArtifactRoot',root],{windowsHide:true,encoding:'utf8'});if(r.status!==0)throw Error('Assessment fixture failed: '+r.stderr+' '+r.stdout)}
const read=n=>JSON.parse(fs.readFileSync(path.join(root,n),'utf8').replace(/^\uFEFF/,''));
const report=read('weighted-report.json'),progress=read('progress.json');
const html=fs.readFileSync(path.join(__dirname,'..','claude-panel.html'),'utf8').replaceAll('__THEME__','anime').replaceAll('__CSL_TOKEN__','synthetic').replaceAll('__CSL_TESTMODE__','0').replaceAll('__CSL_USERPROFILE__','Fixture').replaceAll('__CSL_COMPUTERNAME__','Fixture');
let phase=0,live=null,corrupt=false,passed=0;const errors=[];
function check(ok,name){if(!ok)throw Error(name);passed++;console.log('PASS: '+name)}
const event=(n,Level,Weight,Text)=>({Group:report.stages[n-1],Level,Weight,Text});
const summary=events=>({timestampUtc:new Date().toISOString(),checkEvents:events,routes:{status:'observed',observed:2,message:'合成连接'},remaining:events.filter(e=>e.Level==='FAIL').length,unknown:events.filter(e=>e.Level==='UNKNOWN').length});
const server=http.createServer((req,res)=>{const p=new URL(req.url,'http://fixture').pathname;res.setHeader('Cache-Control','no-store');res.setHeader('Content-Type',p==='/'?'text/html;charset=utf-8':'application/json');
 if(p==='/')return res.end(html);
 if(p==='/api/poll')return res.end(JSON.stringify(phase<2?{next:0,lines:[],done:false,progress:progress[phase],elapsedSeconds:phase+1,timeoutSeconds:120}:{next:0,lines:[],done:true,complete:true,report:corrupt?{...report,score:100}:report}));
 if(p==='/api/risk-status')return res.end(JSON.stringify({ok:true,active:!!live,summary:live}));res.end('{"ok":true}');});
(async()=>{await new Promise(r=>server.listen(0,'127.0.0.1',r));const browser=await chromium.launch({headless:true,executablePath:process.env.CSL_EDGE_EXE});
 try{
  const page=await browser.newPage({viewport:{width:1120,height:1000}});page.on('pageerror',e=>errors.push(e.message));await page.addInitScript(()=>{window.RTCPeerConnection=class{constructor(){throw Error('fixture')}}});
  await page.goto('http://127.0.0.1:'+server.address().port);
  await page.waitForFunction(()=>document.getElementById('score').textContent==='92');
  check((await page.locator('#state').innerText()).includes('正在检查'),'score updates while the real check is still in progress');
  check((await page.locator('#coverage').innerText()).includes('2/15'),'progress coverage is linked to received evidence');
  check(await page.locator('#cpass').innerText()==='1','two passing log lines in one group count as one passed group');
  phase=1;await page.waitForFunction(()=>document.getElementById('score').textContent==='67');
  check(await page.locator('#cfail').innerText()==='1','new failure updates both counter and live provisional score');
  check((await page.locator('.penalty').nth(2).innerText())==='-25分','a card shows its actual numeric deduction');
  phase=2;await page.waitForFunction(()=>!document.getElementById('bCheck').disabled);
  check(await page.locator('#score').innerText()==='67','final score agrees with weighted PowerShell assessment');
  check(await page.locator('#cpass').innerText()==='8','final pass counter counts groups rather than rows');
  check(await page.locator('#creference').innerText()==='4','reference and unavailable groups are separate from passed groups');
  check((await page.locator('#score').getAttribute('title')).includes('-25 分'),'score explains actual deduction sources');
  await page.screenshot({path:path.join(root,'score-67.png'),fullPage:true,animations:'disabled'});
  live=summary([event(2,'PASS',0,'时区复查恢复'),event(3,'PASS',0,'节点复查恢复'),event(14,'PASS',0,'已观测两条连接'),event(15,'INFO',0,'无可用日志')]);
  await page.waitForFunction(()=>document.getElementById('score').textContent==='100',null,{timeout:12000});
  check(await page.locator('#cfail').innerText()==='0'&&await page.locator('#cwarn').innerText()==='0','verified live recovery clears previous failures and warnings');
  check(await page.locator('#cunknown').innerText()==='0','connection evidence resolves the pending group');
  check((await page.locator('#hint').innerText()).includes('100/100'),'footer and ring use the same updated score');
  live=summary([event(2,'WARN',8,'时区再次偏离标准')]);await page.waitForFunction(()=>document.getElementById('score').textContent==='92',null,{timeout:12000});
  check(await page.locator('#cwarn').innerText()==='1','a fresh timezone mismatch lowers score and updates warning state');
  live=summary([event(1,'FAIL',25,'TUN 未就绪')]);await page.waitForFunction(()=>document.getElementById('score').textContent==='67',null,{timeout:12000});
  check(await page.locator('#cfail').innerText()==='1','a live TUN failure changes the score without another full check');
  live=summary([event(1,'PASS',0,'TUN 恢复'),event(2,'PASS',0,'时区恢复')]);await page.waitForFunction(()=>document.getElementById('score').textContent==='100',null,{timeout:12000});
  check((await page.locator('.penalty').nth(0).innerText())==='','observed recovery removes stale card deductions');
  await page.screenshot({path:path.join(root,'score-restored.png'),fullPage:true,animations:'disabled'});
  live=summary([event(13,'FAIL',25,'地区核对失败'),event(14,'FAIL',25,'连接路径偏离')]);await page.waitForFunction(()=>document.getElementById('score').textContent==='50',null,{timeout:12000});
  check(await page.locator('#cfail').innerText()==='2','independent actual failures contribute their own weights');
  live={...summary([event(13,'PASS',0,'旧成功结果'),event(14,'PASS',0,'旧成功结果')]),timestampUtc:new Date(Date.parse(report.timestamp)-1000).toISOString()};
  await page.waitForTimeout(5500);check(await page.locator('#score').innerText()==='50','an old snapshot cannot overwrite newer real failures');
  await page.evaluate(()=>{st.lastLiveAt=Date.now()-61000;markObservationStale()});
  check(await page.locator('#score').innerText()==='50','expired observations retain confirmed deductions');
  check(Number(await page.locator('#cunknown').innerText())>0,'expired successful observations become pending rather than silently passed');
  corrupt=true;live=null;await page.click('#bCheck');await page.waitForFunction(()=>document.getElementById('state').textContent==='检查未完成');
  check(await page.locator('#score').innerText()==='--','a final score inconsistent with the actual evidence is refused');
  check((await page.locator('#hint').innerText()).includes('不一致'),'the inconsistency has a useful visible explanation');
  check(errors.length===0,'all score changes are free of JavaScript errors');
  fs.writeFileSync(path.join(root,'score-results.json'),JSON.stringify({passed,errors,source:'PowerShell helper fixtures; non-mutating browser transitions'},null,2));console.log(JSON.stringify({passed,artifacts:root}));
 }finally{await browser.close();await new Promise(r=>server.close(r))}
})().catch(e=>{console.error(e.stack);process.exitCode=1;server.close()});
